function getDailyLevel(dateStr) {
  let h = 0;
  for (let i = 0; i < dateStr.length; i++) h = (h * 31 + dateStr.charCodeAt(i)) >>> 0;
  const src = DAILY_LEVELS[h % DAILY_LEVELS.length];
  return JSON.parse(JSON.stringify(src));
}
